/// <summary>
/// Example GUPPricingAttribute of table <c>RetailInventTable</c> field ItemId.
/// </summary>
/// [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Product, GUPPricingAttributeSourceLevel::Line)]
internal class GUPPricingAttributeRetailInventTableItemId extends GUPPricingAttributeRetailInventTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(RetailInventTable, ItemId);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);
    RetailInventTable retailInventTable;
    while select ItemId from retailInventTable
        group by ItemId
    {
        ret.add(retailInventTable.ItemId);
    }
    return ret;
}

    protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
    {
        QueryBuildRange qbr;

        qbr = _qbds.addRange(fieldNum(RetailInventTable, ItemId));
        qbr.value(queryValue(_value));
    }
